"""Audit descriptive concentration and production subunit coverage; do not alter CMT/DE settings."""
from pathlib import Path
import pandas as pd,numpy as np,json,hashlib,tarfile
r=Path(__file__).resolve().parents[1];o=r/'audit';d=r/'results/global';c=r/'results/cytokine'
s=pd.read_csv(next(d.glob('*_significant_means_*.txt')),sep='\t').set_index('id_cp_interaction');cols=[x for x in s if '|' in x];members=pd.read_csv(o/'network_members.tsv',sep='\t');rows=[];lrrows=[]
for cm,g in members.groupby('cm'):
 nodes=set(g.subCluster);pc=[x for x in cols if x.split('|')[0] in nodes and x.split('|')[1] in nodes and x.split('|')[0]!=x.split('|')[1]];v=s[pc].notna();counts=v.sum().sort_values(ascending=False);lr=v.sum(axis=1).sort_values(ascending=False);total=int(counts.sum());active=int((counts>0).sum());rows.append(dict(cm=cm,n_pairs=len(pc),n_nonzero_pairs=active,total_CCI=total,top1_pair_fraction=counts.head(1).sum()/total if total else np.nan,top3_pair_fraction=counts.head(3).sum()/total if total else np.nan,top10_LR_fraction=lr.head(10).sum()/total if total else np.nan,unique_LR=int((lr>0).sum())))
 for key,n in lr.items():lrrows.append(dict(cm=cm,id_cp_interaction=key,n_nonself_pairs=int(n),n_possible_pairs=len(pc),fraction_pairs=n/len(pc)))
pd.DataFrame(rows).to_csv(o/'global_concentration.tsv',sep='\t',index=False);pd.DataFrame(lrrows).to_csv(o/'global_LR_CM_prevalence.tsv',sep='\t',index=False)
# Verify every required cytokine subunit, not merely one retained subunit row.
z=np.load(r/'private/CMT_identity_stats.npz');ix=pd.read_csv(r/'private/CMT_identity_stats_index.tsv',sep='\t');a=pd.read_csv(c/'response_full_family_reviewed.tsv',sep='\t');net=pd.read_csv(c/'production_response_network.tsv',sep='\t');alias={'IFNg':['IFNG'],'TNFa':['TNF'],'IL12':['IL12A','IL12B'],'IL23':['IL23A','IL12B'],'IL27':['IL27','EBI3'],'TGFb1':['TGFB1']};review=[]
for row in net.drop_duplicates(['cm','producer','cytokine','receiver','direction']).itertuples():
 source=a[(a.cm==row.cm)&(a.identity==row.receiver)&(a.cytokine==row.cytokine)&(a.direction==row.direction)&(a.branch=='project_directional_measured_universe')].iloc[0];required=alias.get(source.cytokine_symbol_mouse,[source.cytokine_symbol_mouse.upper()]);mask=(ix.CMT==row.cm)&(ix.identity==row.producer);n=int(z['n'][mask].sum());means={g:float(z['sums'][mask][:,list(z['genes']).index(g)].sum()/n) for g in required if g in z['genes']};missing=[g for g in required if g not in means];passed=not missing and all(v>.1 for v in means.values());review.append(dict(cm=row.cm,producer=row.producer,cytokine=row.cytokine,receiver=row.receiver,direction=row.direction,response_q=row.response_q,required_subunits=';'.join(required),measured_subunits=';'.join(means),missing_subunits=';'.join(missing),min_subunit_mean=min(means.values()) if means else np.nan,status='all_required_subunits_expressed' if passed else 'partial_subunit_candidate_only'))
pd.DataFrame(review).to_csv(c/'production_response_network_subunit_review.tsv',sep='\t',index=False)
files=[o/'global_concentration.tsv',o/'global_LR_CM_prevalence.tsv',r/'results/summary/global_cellpair_CCI.tsv',r/'results/summary/global_CM_CCI.tsv']+[c/n for n in ['response_full_family_reviewed.tsv','identity_eligibility.tsv','production_response_network_subunit_review.tsv','production_response_network.tsv']]
with tarfile.open(r/'descriptive_review_tables.tar.gz','w:gz') as tar:
 for p in files:tar.add(p,arcname=p.name,recursive=False)
print(json.dumps({'package_bytes':(r/'descriptive_review_tables.tar.gz').stat().st_size,'sha256':hashlib.sha256((r/'descriptive_review_tables.tar.gz').read_bytes()).hexdigest(),'network_original_subunit_rows':len(net),'network_unique_edges':len(review),'network_qualified_edges':sum(x['status']=='all_required_subunits_expressed' for x in review)},indent=2))
